SELECT count(*) AS records, count(DISTINCT order_number) AS orders, count(DISTINCT product_mlfb) AS products, count(DISTINCT test_station_identifier) AS stations, count(*) FILTER (WHERE G0003 IS NOT NULL) AS code_present, round(100.0 * count(*) FILTER (WHERE G0003 IS NOT NULL) / nullif(count(*), 0), 2) AS code_present_pct, count(*) FILTER (WHERE is_last_measurement = false) AS non_last, round(100.0 * count(*) FILTER (WHERE is_last_measurement = false) / nullif(count(*), 0), 2) AS non_last_pct
FROM ap
WHERE ($date_from IS NULL OR CAST(inspection_date AS DATE) >= $date_from) AND ($date_to IS NULL OR CAST(inspection_date AS DATE) < $date_to) AND ($source IS NULL OR source = $source) AND ($station IS NULL OR test_station_identifier = $station) AND ($product IS NULL OR product_mlfb = $product) AND ($order IS NULL OR order_number = $order)
